// The parts of contracts/CanaryRegistry.sol the workflow uses.
// Full ABI: contracts/out/CanaryRegistry.abi.json (generated by `npm run compile` in /contracts).
import { parseAbiParameters } from 'viem'

export const CanaryRegistry = [
	{
		type: 'function',
		name: 'statusOf',
		inputs: [{ name: 'caseId', type: 'bytes32' }],
		outputs: [
			{ name: 'level', type: 'uint8' },
			{ name: 'trailHash', type: 'bytes32' },
			{ name: 'collapsed', type: 'bool' },
		],
		stateMutability: 'view',
	},
] as const

// Report envelope expected by CanaryRegistry.onReport: abi.encode(uint8 kind, bytes body)
export const REPORT_ALERT = 1
export const REPORT_COLLAPSE = 2
export const ReportEnvelopeParams = parseAbiParameters('uint8 kind, bytes body')
export const AlertBodyParams = parseAbiParameters(
	'bytes32 caseId, string symbol, address token, uint8 level, uint32 promoters, bytes32 trailHash',
)
// liquidityBefore / liquidityNow are US cents (USD * 100)
export const CollapseBodyParams = parseAbiParameters(
	'bytes32 caseId, address token, uint256 liquidityBefore, uint256 liquidityNow, uint16 dropBps',
)
